#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string s;
    std::getline(std::cin, s);
    int cnt = 0;
    std::string gk;
    for (char c : s) {
        if (c == 'a' && s.substr(&c - &s[0], 2) == "at") {
            gk += '@';
            ++c; // skip next character
        } else if (c == 'd' && s.substr(&c - &s[0], 3) == "dot") {
            gk += '.';
            c += 2; // skip next two characters
        } else {
            gk += c;
        }
    }
    std::vector<std::string> k;
    for (char c : gk) {
        k.push_back(std::string(1, c));
    }
    int n = k.size();

    if (n > 0) {
        if (k[0] == ".") {
            k[0] = "dot";
        }
        if (k[n - 1] == ".") {
            k[n - 1] = "dot";
        }
        if (k[0] == "@") {
            k[0] = "at";
        }
        if (k[n - 1] == "@") {
            k[n - 1] = "at";
        }
    }

    for (int x = 0; x < n; ++x) {
        if (k[x] == "@" && cnt == 0) {
            cnt = 1;
        } else if (k[x] == "@") {
            k[x] = "at";
        }
        std::cout << k[x];
    }
    return 0;
}
